args.command:
node -e '
const SIDES=7,R=250;
const local=Array.from({length:SIDES},(_,i)=>{
  const a=-Math.PI/2+(i*2*Math.PI)/SIDES;
  return {x:R*Math.cos(a),y:R*Math.sin(a)};
});
for (const v of local) console.log(v.x.toFixed(2), v.y.toFixed(2));
for (let i=0;i<SIDES;i++){
  const s=local[i], e=local[(i+1)%SIDES];
  const ex=e.x-s.x, ey=e.y-s.y, len=Math.hypot(ex,ey);
  const nx=ey/len, ny=-ex/len;
  const mx=(s.x+e.x)/2, my=(s.y+e.y)/2;
  const dot=nx*mx+ny*my;
  console.log("edge",i,"mid",mx.toFixed(1),my.toFixed(1),"n",nx.toFixed(3),ny.toFixed(3),"dotMid",dot.toFixed(1), dot>0?"OUTWARD":"INWARD");
}
'

