args.command:
node << 'EOF'
const SIDES = 7;
const POLY_R = 250;
const BALL_R = 15;
const GRAVITY = 500;
const RESTITUTION = 0.8;
const FRICTION = 0.98;
const OMEGA = 0.5;
const SLOP = 1e-3;

const local = Array.from({ length: SIDES }, (_, i) => {
  const a = -Math.PI / 2 + (i * 2 * Math.PI) / SIDES;
  return { x: POLY_R * Math.cos(a), y: POLY_R * Math.sin(a) };
});
const walls = local.map((start, i) => {
  const end = local[(i + 1) % SIDES];
  const ex = end.x - start.x;
  const ey = end.y - start.y;
  const len = Math.hypot(ex, ey);
  let nx = ey / len;
  let ny = -ex / len;
  const mx = (start.x + end.x) / 2;
  const my = (start.y + end.y) / 2;
  if (nx * mx + ny * my < 0) { nx = -nx; ny = -ny; }
  return { sx: start.x, sy: start.y, ex, ey, invLenSq: 1 / (len * len), nx, ny };
});

let angle = 0;
const ball = { x: 0, y: 0, vx: 0, vy: 0 };
let cx = 0, cy = 0;

function penetration(lx, ly) {
  let max = -Infinity;
  for (const w of walls) {
    const pen = (lx - w.sx) * w.nx + (ly - w.sy) * w.ny + BALL_R;
    if (pen > max) max = pen;
  }
  return max;
}

function collide() {
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);
  const rx = ball.x - cx;
  const ry = ball.y - cy;
  let lx = cos * rx + sin * ry;
  let ly = -sin * rx + cos * ry;
  let lvx = cos * ball.vx + sin * ball.vy;
  let lvy = -sin * ball.vx + cos * ball.vy;

  for (let pass = 0; pass < 16; pass++) {
    let worst = 0;
    let idx = -1;
    for (let i = 0; i < SIDES; i++) {
      const w = walls[i];
      const pen = (lx - w.sx) * w.nx + (ly - w.sy) * w.ny + BALL_R;
      if (pen > worst) { worst = pen; idx = i; }
    }
    if (idx < 0) break;
    const w = walls[idx];
    const dx = lx - w.sx;
    const dy = ly - w.sy;
    lx -= w.nx * (worst + SLOP);
    ly -= w.ny * (worst + SLOP);
    const t = Math.max(0, Math.min(1, (dx * w.ex + dy * w.ey) * w.invLenSq));
    const px = w.sx + w.ex * t;
    const py = w.sy + w.ey * t;
    const wvx = -OMEGA * py;
    const wvy = OMEGA * px;
    let relx = lvx - wvx;
    let rely = lvy - wvy;
    const vn = relx * w.nx + rely * w.ny;
    if (vn > 0) {
      relx -= (1 + RESTITUTION) * vn * w.nx;
      rely -= (1 + RESTITUTION) * vn * w.ny;
      const nAfter = relx * w.nx + rely * w.ny;
      const tx = (relx - nAfter * w.nx) * FRICTION;
      const ty = (rely - nAfter * w.ny) * FRICTION;
      lvx = tx + nAfter * w.nx + wvx;
      lvy = ty + nAfter * w.ny + wvy;
    }
  }

  ball.x = cx + cos * lx - sin * ly;
  ball.y = cy + sin * lx + cos * ly;
  ball.vx = cos * lvx - sin * lvy;
  ball.vy = sin * lvx + cos * lvy;
  return penetration(lx, ly);
}

function step(dt) {
  const travel = (Math.hypot(ball.vx, ball.vy) + Math.abs(OMEGA) * POLY_R) * dt + 0.5 * GRAVITY * dt * dt;
  const n = Math.max(1, Math.min(240, Math.ceil(travel / (BALL_R * 0.25))));
  const h = dt / n;
  let maxPen = 0;
  for (let i = 0; i < n; i++) {
    angle += OMEGA * h;
    ball.vy += GRAVITY * h;
    ball.x += ball.vx * h;
    ball.y += ball.vy * h;
    const pen = collide();
    if (pen > maxPen) maxPen = pen;
  }
  return maxPen;
}

let maxPen = 0;
let maxSpeed = 0;
let minInside = Infinity;
for (let t = 0; t < 120; t += 1/60) {
  const pen = step(1/60);
  if (pen > maxPen) maxPen = pen;
  const sp = Math.hypot(ball.vx, ball.vy);
  if (sp > maxSpeed) maxSpeed = sp;
  const cos = Math.cos(angle), sin = Math.sin(angle);
  const rx = ball.x, ry = ball.y;
  const lx = cos * rx + sin * ry;
  const ly = -sin * rx + cos * ry;
  const p = penetration(lx, ly);
  if (p < minInside) minInside = p;
  if (p > 0.5) {
    console.log("ESCAPE", t.toFixed(3), "pen", p, "pos", lx.toFixed(2), ly.toFixed(2), "v", sp.toFixed(1));
    break;
  }
}
console.log({ maxPen, maxSpeed, minInside, angle, ball });

// stress: huge velocity toward a corner
angle = 0.3;
ball.x = 0; ball.y = 0; ball.vx = 4000; ball.vy = -3000;
maxPen = 0;
let escaped = false;
for (let i = 0; i < 600; i++) {
  const pen = step(1/60);
  if (pen > maxPen) maxPen = pen;
  const cos = Math.cos(angle), sin = Math.sin(angle);
  const lx = cos * ball.x + sin * ball.y;
  const ly = -sin * ball.x + cos * ball.y;
  const p = penetration(lx, ly);
  if (p > 0.5) { escaped = true; console.log("stress escape", i, p, lx, ly); break; }
}
console.log("stress", { escaped, maxPen, speed: Math.hypot(ball.vx, ball.vy) });
EOF

