const page = await browser.getPage("bouncing-ball");
function orientationScript() {
  const canvas = document.getElementById("c");
  const ctx = canvas.getContext("2d");
  const { data, width, height } = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const cx = width / 2;
  const cy = height / 2;
  let best = [];
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const i = (y * width + x) * 4;
      if (data[i] > 220 && data[i + 1] > 220 && data[i + 2] > 220) {
        const dx = x - cx;
        const dy = y - cy;
        const r2 = dx * dx + dy * dy;
        if (r2 > 200 * 200) best.push({ x, y, a: Math.atan2(dy, dx), r2 });
      }
    }
  }
  best.sort((p, q) => q.r2 - p.r2);
  const verts = [];
  for (const p of best) {
    if (verts.every((v) => Math.hypot(v.x - p.x, v.y - p.y) > 30)) verts.push(p);
    if (verts.length === 7) break;
  }
  verts.sort((p, q) => p.a - q.a);
  return verts.map((v) => ({ x: Math.round(v.x), y: Math.round(v.y), deg: +(v.a * 180 / Math.PI).toFixed(1) }));
}
const a = await page.evaluate(orientationScript);
await page.waitForTimeout(1000);
const b = await page.evaluate(orientationScript);
console.log(JSON.stringify({ a, b }, null, 2));
