const page = await browser.getPage("bouncing-ball");
const result = await page.evaluate(() => {
  const canvas = document.getElementById("c");
  const ctx = canvas.getContext("2d");
  const { data, width, height } = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const cx = width / 2, cy = height / 2;
  let rx = 0, ry = 0, rn = 0;
  const whites = [];
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const i = (y * width + x) * 4;
      const r = data[i], g = data[i + 1], b = data[i + 2];
      if (r > 200 && g < 40 && b < 40) { rx += x; ry += y; rn++; }
      if (r > 220 && g > 220 && b > 220) {
        const dx = x - cx, dy = y - cy;
        if (dx * dx + dy * dy > 200 * 200) whites.push({ x, y });
      }
    }
  }
  const ball = { x: rx / rn, y: ry / rn, n: rn };
  const verts = [];
  const ranked = whites.map((p) => ({ ...p, r2: (p.x - cx) ** 2 + (p.y - cy) ** 2 })).sort((a, b) => b.r2 - a.r2);
  for (const p of ranked) {
    if (verts.every((v) => Math.hypot(v.x - p.x, v.y - p.y) > 30)) verts.push(p);
    if (verts.length === 7) break;
  }
  verts.sort((p, q) => Math.atan2(p.y - cy, p.x - cx) - Math.atan2(q.y - cy, q.x - cx));
  let maxOut = -Infinity;
  for (let i = 0; i < verts.length; i++) {
    const a = verts[i], b = verts[(i + 1) % verts.length];
    const ex = b.x - a.x, ey = b.y - a.y;
    const len = Math.hypot(ex, ey);
    let nx = ey / len, ny = -ex / len;
    const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
    if (nx * (mx - cx) + ny * (my - cy) < 0) { nx = -nx; ny = -ny; }
    const signed = (ball.x - a.x) * nx + (ball.y - a.y) * ny;
    if (signed > maxOut) maxOut = signed;
  }
  return { ball, maxOutwardSigned: maxOut, inside: maxOut < 1 };
});
console.log(JSON.stringify(result, null, 2));
